enum CoreError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {



    case TotalOverflow
    case InvalidTorrent(reason: String
    )
    case InvalidMagnet(reason: String
    )
    case Engine(reason: String
    )
    case InvalidUrl(reason: String
    )
    case InvalidConfiguration(reason: String
    )
    case DependencyUnavailable(reason: String
    )
    case Extraction(reason: String
    )






    public var errorDescription: String? {
        String(reflecting: self)
    }

}

#if compiler(>=6)
extension CoreError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeCoreError: FfiConverterRustBuffer {
    typealias SwiftType = CoreError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CoreError {
        let variant: Int32 = try readInt(&buf)
        switch variant {




        case 1: return .TotalOverflow
        case 2: return .InvalidTorrent(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 3: return .InvalidMagnet(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 4: return .Engine(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 5: return .InvalidUrl(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 6: return .InvalidConfiguration(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 7: return .DependencyUnavailable(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 8: return .Extraction(
            reason: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: CoreError, into buf: inout [UInt8]) {
        switch value {





        case .TotalOverflow:
            writeInt(&buf, Int32(1))


        case let .InvalidTorrent(reason):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(reason, into: &buf)


        case let .InvalidMagnet(reason):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(reason, into: &buf)


        case let .Engine(reason):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(reason, into: &buf)


        case let .InvalidUrl(reason):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(reason, into: &buf)


        case let .InvalidConfiguration(reason):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(reason, into: &buf)


        case let .DependencyUnavailable(reason):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(reason, into: &buf)


        case let .Extraction(reason):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(reason, into: &buf)

        }
    }
}


