enum StateMachineError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {



    case Open(reason: String
    )
    case Rejected(reason: String
    )
    case Engine(reason: String
    )
    case InvalidIdentifier(reason: String
    )
    case Persistence(reason: String
    )






    public var errorDescription: String? {
        String(reflecting: self)
    }

}

#if compiler(>=6)
extension StateMachineError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeStateMachineError: FfiConverterRustBuffer {
    typealias SwiftType = StateMachineError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> StateMachineError {
        let variant: Int32 = try readInt(&buf)
        switch variant {




        case 1: return .Open(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Rejected(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Engine(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 4: return .InvalidIdentifier(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 5: return .Persistence(
            reason: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: StateMachineError, into buf: inout [UInt8]) {
        switch value {





        case let .Open(reason):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(reason, into: &buf)


        case let .Rejected(reason):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(reason, into: &buf)


        case let .Engine(reason):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(reason, into: &buf)


        case let .InvalidIdentifier(reason):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(reason, into: &buf)


        case let .Persistence(reason):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(reason, into: &buf)

        }
    }
}


